    cols = len(grid[0])
    bg = 6

    output = [[bg for _ in range(cols)] for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            output[r][c] = grid[r][c]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                if r - 1 >= 0:
                    output[r-1][c] = 8
                    output[r-1][c+1] = 5
                output[r][c] = 0
                output[r][c+1] = 5
